mapper.select:
SELECT id, household_id, name, management_type, category_id, brand_id, unit_id,
       cover_file_id, memo, expiry_reminder_mode, expiry_reminder_days,
       low_stock_mode, low_stock_threshold, status, archived_at, archived_by,
       created_at, updated_at, version
FROM catalog_item

    household_id = #{householdId}

        AND name ILIKE CONCAT('%', #{q}, '%')


        AND management_type = #{managementType}


        AND category_id = #{categoryId}


        AND brand_id = #{brandId}


        AND status = #{status}


        AND EXISTS (
            SELECT 1 FROM catalog_item_tag t
            WHERE t.item_id = catalog_item.id AND t.tag_id = #{tagId}
        )


ORDER BY ${orderBy}

SELECT id, household_id, name, management_type, category_id, brand_id, unit_id, cover_file_id, memo, expiry_reminder_mode, expiry_reminder_days, low_stock_mode, low_stock_threshold, status, archived_at, archived_by, created_at, updated_at, version FROM catalog_item
household_id = #{householdId} AND status = 'ACTIVE'
AND id = #{itemId}
AND name ILIKE CONCAT('%', #{nameContains}, '%')
ORDER BY name ASC, id ASC LIMIT #{limit}

mapper.update:
UPDATE catalog_item
SET cover_file_id = NULL,
    updated_at = CURRENT_TIMESTAMP,
    version = version + 1
WHERE household_id = #{householdId}
  AND id = #{itemId}
  AND cover_file_id = #{fileId}
